mapper.select:
SELECT cu.id, cu.template_id AS templateId, cu.status, cu.used_time AS usedTime, cu.create_time AS createTime, ct.name, ct.type, ct.condition_amt AS conditionAmt, ct.discount_amt AS discountAmt, ct.discount_rate AS discountRate, ct.start_time AS startTime, ct.end_time AS endTime FROM coupon_user cu JOIN coupon_template ct ON cu.template_id = ct.id WHERE cu.user_id = #{userId} AND cu.del_flag = '0' AND ct.del_flag = '0'
AND cu.status = #{status}
ORDER BY cu.create_time DESC

SELECT COUNT(*)
FROM coupon_user
WHERE user_id = #{userId}
  AND template_id = #{templateId}
  AND del_flag = '0'

SELECT template_id AS templateId, COUNT(*) AS cnt FROM coupon_user WHERE user_id = #{userId} AND template_id IN
#{tid}
AND del_flag = '0' GROUP BY template_id
